"use client"

import ReactMarkdown, { type Components } from "react-markdown"
import remarkGfm from "remark-gfm"

interface ProblemDescriptionProps {
  markdown: string
}

// Matches the ProblemPanel's compact text-xs style. Descriptions are Markdown
// generated by the backend seed script from LeetCode's HTML.
const components: Components = {
  p: ({ children }) => <p className="mb-2.5 last:mb-0">{children}</p>,
  ul: ({ children }) => <ul className="list-disc pl-4 mb-2.5 space-y-1 last:mb-0">{children}</ul>,
  ol: ({ children }) => <ol className="list-decimal pl-4 mb-2.5 space-y-1 last:mb-0">{children}</ol>,
  li: ({ children }) => <li className="leading-relaxed">{children}</li>,
  strong: ({ children }) => (
    <strong className="font-semibold text-zinc-800 dark:text-zinc-200">{children}</strong>
  ),
  em: ({ children }) => <em className="italic">{children}</em>,
  // Inline code by default; inside <pre> the block styles below take over.
  code: ({ children }) => (
    <code className="px-1 py-0.5 rounded bg-zinc-100 dark:bg-zinc-800 text-zinc-800 dark:text-zinc-200 text-[11px] font-mono">
      {children}
    </code>
  ),
  pre: ({ children }) => (
    <pre className="my-2.5 overflow-x-auto rounded-lg bg-zinc-950 p-3 text-[11px] leading-relaxed text-zinc-100 [&>code]:bg-transparent [&>code]:p-0 [&>code]:text-zinc-100">
      {children}
    </pre>
  ),
  a: ({ children, href }) => (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      className="text-violet-600 dark:text-violet-400 underline underline-offset-2"
    >
      {children}
    </a>
  ),
}

export function ProblemDescription({ markdown }: ProblemDescriptionProps) {
  return (
    <div className="text-xs text-zinc-600 dark:text-zinc-400 leading-relaxed break-words">
      <ReactMarkdown remarkPlugins={[remarkGfm]} components={components}>
        {markdown}
      </ReactMarkdown>
    </div>
  )
}
